import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import ManagerTripApprovals from './ManagerTripApprovals';

const EnhancedManagerDashboard = () => {
  const [profile, setProfile] = useState(null);
  const [stats, setStats] = useState({
    totalEmployees: 0,
    pendingBills: 0,
    pendingTrips: 0,
    totalApproved: 0,
    monthlyExpenses: 0,
    teamPerformance: 95
  });
  const [employees, setEmployees] = useState([]);
  const [pendingBills, setPendingBills] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const navigate = useNavigate();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      // Fetch profile
      const profileResponse = await axios.get('http://localhost:8000/profile', { headers });
      setProfile(profileResponse.data);

      // Mock data for demonstration
      setStats({
        totalEmployees: 24,
        pendingBills: 8,
        pendingTrips: 3,
        totalApproved: 156,
        monthlyExpenses: 2450000,
        teamPerformance: 95
      });

      setEmployees([
        { id: 1, name: 'John Doe', department: 'Engineering', bills: 3, amount: 15000, status: 'active' },
        { id: 2, name: 'Jane Smith', department: 'Marketing', bills: 2, amount: 8500, status: 'active' },
        { id: 3, name: 'Mike Johnson', department: 'Sales', bills: 5, amount: 22000, status: 'active' }
      ]);

      setPendingBills([
        { id: 1, employee: 'John Doe', description: 'Client Dinner', amount: 3500, date: '2024-01-15', category: 'Food' },
        { id: 2, employee: 'Jane Smith', description: 'Conference Travel', amount: 12000, date: '2024-01-14', category: 'Travel' },
        { id: 3, employee: 'Mike Johnson', description: 'Office Supplies', amount: 2800, date: '2024-01-13', category: 'Office' }
      ]);

    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        navigate('/login');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  };

  const approveBill = async (billId) => {
    try {
      // Mock approval - in real app, call API
      setPendingBills(prev => prev.filter(bill => bill.id !== billId));
      setStats(prev => ({ ...prev, pendingBills: prev.pendingBills - 1, totalApproved: prev.totalApproved + 1 }));
      alert('Bill approved successfully!');
    } catch (error) {
      console.error('Error approving bill:', error);
      alert('Failed to approve bill');
    }
  };

  const rejectBill = async (billId) => {
    try {
      // Mock rejection - in real app, call API
      setPendingBills(prev => prev.filter(bill => bill.id !== billId));
      setStats(prev => ({ ...prev, pendingBills: prev.pendingBills - 1 }));
      alert('Bill rejected');
    } catch (error) {
      console.error('Error rejecting bill:', error);
      alert('Failed to reject bill');
    }
  };

  if (loading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>Loading manager dashboard...</p>
      </div>
    );
  }

  return (
    <div className="manager-dashboard">
      {/* Header */}
      <div className="dashboard-header">
        <div className="header-content">
          <div className="header-info">
            <div className="user-avatar">
              {profile?.full_name?.charAt(0) || profile?.username?.charAt(0) || 'M'}
            </div>
            <div className="user-details">
              <h1 className="user-name">
                Manager Dashboard
              </h1>
              <p className="user-role">
                Welcome, {profile?.full_name || profile?.username} • {profile?.department} Manager
              </p>
            </div>
          </div>
          <div className="header-actions">
            <button className="btn btn-outline btn-sm" onClick={() => navigate('/profile')}>
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M20 21V19C20 17.9391 19.5786 16.9217 18.8284 16.1716C18.0783 15.4214 17.0609 15 16 15H8C6.93913 15 5.92172 15.4214 5.17157 16.1716C4.42143 16.9217 4 17.9391 4 19V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <circle cx="12" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
              Profile
            </button>
            <button className="btn btn-error btn-sm" onClick={handleLogout}>
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M9 21H5C4.46957 21 3.96086 20.7893 3.58579 20.4142C3.21071 20.0391 3 19.5304 3 19V5C3 4.46957 3.21071 3.96086 3.58579 3.58579C3.96086 3.21071 4.46957 3 5 3H9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <polyline points="16,17 21,12 16,7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <line x1="21" y1="12" x2="9" y2="12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
              Logout
            </button>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="stats-section">
        <div className="stats-grid">
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--primary-100)', color: 'var(--primary-600)' }}>
              👥
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Team Members</h3>
              <p className="stats-card-value">{stats.totalEmployees}</p>
              <p className="stats-card-change positive">+2 this month</p>
            </div>
          </div>
          
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--warning-100)', color: 'var(--warning-600)' }}>
              ⏳
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Pending Bills</h3>
              <p className="stats-card-value">{stats.pendingBills}</p>
              <p className="stats-card-change neutral">Awaiting review</p>
            </div>
          </div>
          
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--success-100)', color: 'var(--success-600)' }}>
              ✅
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Approved This Month</h3>
              <p className="stats-card-value">{stats.totalApproved}</p>
              <p className="stats-card-change positive">+12% from last month</p>
            </div>
          </div>
          
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--secondary-100)', color: 'var(--secondary-600)' }}>
              💰
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Monthly Expenses</h3>
              <p className="stats-card-value">{formatCurrency(stats.monthlyExpenses)}</p>
              <p className="stats-card-change negative">+5% from budget</p>
            </div>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="nav-tabs">
        <button
          className={`nav-tab ${activeTab === 'overview' ? 'active' : ''}`}
          onClick={() => setActiveTab('overview')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect x="3" y="3" width="18" height="18" rx="2" ry="2" stroke="currentColor" strokeWidth="2"/>
            <line x1="9" y1="9" x2="15" y2="9" stroke="currentColor" strokeWidth="2"/>
            <line x1="9" y1="15" x2="15" y2="15" stroke="currentColor" strokeWidth="2"/>
          </svg>
          Overview
        </button>
        <button
          className={`nav-tab ${activeTab === 'team' ? 'active' : ''}`}
          onClick={() => setActiveTab('team')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M17 21V19C17 17.9391 16.5786 16.9217 15.8284 16.1716C15.0783 15.4214 14.0609 15 13 15H5C3.93913 15 2.92172 15.4214 2.17157 16.1716C1.42143 16.9217 1 17.9391 1 19V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <circle cx="9" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <path d="M23 21V19C23 18.1645 22.7155 17.3541 22.2094 16.7006C21.7033 16.047 20.9999 15.5866 20.2 15.3859" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <path d="M16 3.13C16.8003 3.33066 17.5037 3.79103 18.0098 4.44466C18.5159 5.09829 18.8003 5.90871 18.8003 6.74435C18.8003 7.57999 18.5159 8.39041 18.0098 9.04404C17.5037 9.69767 16.8003 10.158 16 10.3587" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          Team ({employees.length})
        </button>
        <button
          className={`nav-tab ${activeTab === 'bills' ? 'active' : ''}`}
          onClick={() => setActiveTab('bills')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M14 2H6C5.46957 2 4.96086 2.21071 4.58579 2.58579C4.21071 2.96086 4 3.46957 4 4V20C4 20.5304 4.21071 21.0391 4.58579 21.4142C4.96086 21.7893 5.46957 22 6 22H18C18.5304 22 19.0391 21.7893 19.4142 21.4142C19.7893 21.0391 20 20.5304 20 20V8L14 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <polyline points="14,2 14,8 20,8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          Pending Bills ({pendingBills.length})
        </button>
        <button
          className={`nav-tab ${activeTab === 'trips' ? 'active' : ''}`}
          onClick={() => setActiveTab('trips')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M21 16V8C21 6.89543 20.1046 6 19 6H5C3.89543 6 3 6.89543 3 8V16C3 17.1046 3.89543 18 5 18H19C20.1046 18 21 17.1046 21 16Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <polyline points="7,10 12,15 17,10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          Trip Approvals
        </button>
      </div>

      {/* Tab Content */}
      <div className="tab-content">
        {activeTab === 'overview' && (
          <div className="overview-section">
            <div className="overview-grid">
              <div className="overview-card">
                <h3 className="card-title">Team Performance</h3>
                <div className="performance-chart">
                  <div className="performance-circle">
                    <div className="performance-value">{stats.teamPerformance}%</div>
                  </div>
                  <p className="performance-label">Overall Team Performance</p>
                </div>
              </div>
              
              <div className="overview-card">
                <h3 className="card-title">Recent Activity</h3>
                <div className="activity-list">
                  <div className="activity-item">
                    <div className="activity-icon success">✅</div>
                    <div className="activity-content">
                      <p className="activity-text">Approved John's travel expense</p>
                      <p className="activity-time">2 hours ago</p>
                    </div>
                  </div>
                  <div className="activity-item">
                    <div className="activity-icon warning">⏳</div>
                    <div className="activity-content">
                      <p className="activity-text">New trip request from Jane</p>
                      <p className="activity-time">4 hours ago</p>
                    </div>
                  </div>
                  <div className="activity-item">
                    <div className="activity-icon primary">📄</div>
                    <div className="activity-content">
                      <p className="activity-text">Mike submitted office supplies bill</p>
                      <p className="activity-time">1 day ago</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'team' && (
          <div className="team-section">
            <div className="section-header">
              <h2 className="section-title">Team Members</h2>
              <div className="section-actions">
                <button className="btn btn-outline btn-sm">
                  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2"/>
                    <path d="M21 21L16.65 16.65" stroke="currentColor" strokeWidth="2"/>
                  </svg>
                  Search Team
                </button>
                <button className="btn btn-primary btn-sm">
                  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M16 21V19C16 17.9391 15.5786 16.9217 14.8284 16.1716C14.0783 15.4214 13.0609 15 12 15H5C3.93913 15 2.92172 15.4214 2.17157 16.1716C1.42143 16.9217 1 17.9391 1 19V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <circle cx="8.5" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <line x1="20" y1="8" x2="20" y2="14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <line x1="23" y1="11" x2="17" y2="11" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                  Add Member
                </button>
              </div>
            </div>
            
            <div className="team-grid">
              {employees.map((employee) => (
                <div key={employee.id} className="employee-card">
                  <div className="employee-avatar">
                    {employee.name.charAt(0)}
                  </div>
                  <div className="employee-info">
                    <h3 className="employee-name">{employee.name}</h3>
                    <p className="employee-department">{employee.department}</p>
                    <div className="employee-stats">
                      <div className="stat">
                        <span className="stat-value">{employee.bills}</span>
                        <span className="stat-label">Bills</span>
                      </div>
                      <div className="stat">
                        <span className="stat-value">{formatCurrency(employee.amount)}</span>
                        <span className="stat-label">Total</span>
                      </div>
                    </div>
                  </div>
                  <div className="employee-actions">
                    <button className="btn btn-outline btn-sm">View Details</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'bills' && (
          <div className="bills-section">
            <div className="section-header">
              <h2 className="section-title">Pending Bills</h2>
              <div className="section-stats">
                <span className="stat-badge warning">
                  {pendingBills.length} pending review
                </span>
              </div>
            </div>
            
            <div className="table-container">
              <table className="table">
                <thead>
                  <tr>
                    <th>Employee</th>
                    <th>Description</th>
                    <th>Category</th>
                    <th>Amount</th>
                    <th>Date</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingBills.map((bill) => (
                    <tr key={bill.id}>
                      <td>
                        <div className="employee-cell">
                          <div className="employee-avatar-sm">
                            {bill.employee.charAt(0)}
                          </div>
                          <span className="employee-name">{bill.employee}</span>
                        </div>
                      </td>
                      <td>
                        <span className="bill-description">{bill.description}</span>
                      </td>
                      <td>
                        <span className="badge badge-secondary">{bill.category}</span>
                      </td>
                      <td>
                        <span className="amount">{formatCurrency(bill.amount)}</span>
                      </td>
                      <td>
                        <span className="date">{new Date(bill.date).toLocaleDateString()}</span>
                      </td>
                      <td>
                        <div className="action-buttons">
                          <button 
                            className="btn btn-success btn-sm"
                            onClick={() => approveBill(bill.id)}
                          >
                            ✓ Approve
                          </button>
                          <button 
                            className="btn btn-error btn-sm"
                            onClick={() => rejectBill(bill.id)}
                          >
                            ✗ Reject
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'trips' && (
          <ManagerTripApprovals />
        )}
      </div>

      <style jsx>{`
        .manager-dashboard {
          min-height: 100vh;
          background: linear-gradient(135deg, var(--primary-50) 0%, var(--secondary-50) 100%);
          padding: var(--space-6);
        }

        .dashboard-loading {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          min-height: 100vh;
          gap: var(--space-4);
        }

        .loading-spinner {
          width: 48px;
          height: 48px;
          border: 4px solid var(--secondary-200);
          border-top: 4px solid var(--primary-600);
          border-radius: 50%;
          animation: spin 1s linear infinite;
        }

        .dashboard-header {
          background: white;
          border-radius: var(--radius-2xl);
          padding: var(--space-8);
          margin-bottom: var(--space-8);
          box-shadow: var(--shadow-lg);
          border: 1px solid var(--secondary-100);
        }

        .header-content {
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .header-info {
          display: flex;
          align-items: center;
          gap: var(--space-4);
        }

        .user-avatar {
          width: 64px;
          height: 64px;
          border-radius: var(--radius-full);
          background: linear-gradient(135deg, var(--primary-600), var(--primary-700));
          display: flex;
          align-items: center;
          justify-content: center;
          color: white;
          font-size: var(--text-2xl);
          font-weight: var(--font-bold);
        }

        .user-name {
          font-size: var(--text-3xl);
          font-weight: var(--font-bold);
          color: var(--secondary-900);
          margin: 0 0 var(--space-1) 0;
        }

        .user-role {
          color: var(--secondary-600);
          font-size: var(--text-base);
          margin: 0;
        }

        .header-actions {
          display: flex;
          gap: var(--space-3);
        }

        .stats-section {
          margin-bottom: var(--space-8);
        }

        .stats-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
          gap: var(--space-6);
        }

        .stats-card {
          background: white;
          border-radius: var(--radius-xl);
          padding: var(--space-6);
          box-shadow: var(--shadow-md);
          border: 1px solid var(--secondary-100);
          transition: all var(--transition-base);
          display: flex;
          align-items: center;
          gap: var(--space-4);
        }

        .stats-card:hover {
          box-shadow: var(--shadow-xl);
          transform: translateY(-4px);
        }

        .stats-card-icon {
          width: 56px;
          height: 56px;
          border-radius: var(--radius-xl);
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: var(--text-2xl);
          flex-shrink: 0;
        }

        .stats-card-content {
          flex: 1;
        }

        .stats-card-title {
          font-size: var(--text-sm);
          font-weight: var(--font-medium);
          color: var(--secondary-600);
          margin: 0 0 var(--space-1) 0;
        }

        .stats-card-value {
          font-size: var(--text-3xl);
          font-weight: var(--font-bold);
          color: var(--secondary-900);
          margin: 0 0 var(--space-1) 0;
        }

        .stats-card-change {
          font-size: var(--text-xs);
          font-weight: var(--font-medium);
          margin: 0;
        }

        .stats-card-change.positive {
          color: var(--success-600);
        }

        .stats-card-change.negative {
          color: var(--error-600);
        }

        .stats-card-change.neutral {
          color: var(--secondary-500);
        }

        .nav-tabs {
          display: flex;
          background: white;
          border-radius: var(--radius-xl);
          padding: var(--space-2);
          margin-bottom: var(--space-8);
          box-shadow: var(--shadow-sm);
          border: 1px solid var(--secondary-100);
          overflow-x: auto;
        }

        .nav-tab {
          display: flex;
          align-items: center;
          gap: var(--space-2);
          padding: var(--space-4) var(--space-6);
          background: none;
          border: none;
          font-size: var(--text-base);
          font-weight: var(--font-medium);
          color: var(--secondary-600);
          cursor: pointer;
          border-radius: var(--radius-lg);
          transition: all var(--transition-fast);
          white-space: nowrap;
        }

        .nav-tab svg {
          width: 20px;
          height: 20px;
        }

        .nav-tab:hover {
          color: var(--primary-600);
          background-color: var(--primary-50);
        }

        .nav-tab.active {
          color: var(--primary-600);
          background-color: var(--primary-100);
        }

        .tab-content {
          background: white;
          border-radius: var(--radius-2xl);
          padding: var(--space-8);
          box-shadow: var(--shadow-lg);
          border: 1px solid var(--secondary-100);
        }

        .section-title {
          font-size: var(--text-2xl);
          font-weight: var(--font-bold);
          color: var(--secondary-900);
          margin: 0 0 var(--space-6) 0;
        }

        .section-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: var(--space-6);
        }

        .section-actions {
          display: flex;
          gap: var(--space-3);
        }

        .section-stats {
          display: flex;
          gap: var(--space-3);
        }

        .stat-badge {
          padding: var(--space-2) var(--space-4);
          border-radius: var(--radius-full);
          font-size: var(--text-sm);
          font-weight: var(--font-medium);
        }

        .stat-badge.warning {
          background-color: var(--warning-100);
          color: var(--warning-800);
        }

        .overview-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
          gap: var(--space-8);
        }

        .overview-card {
          background: var(--secondary-50);
          border: 1px solid var(--secondary-200);
          border-radius: var(--radius-xl);
          padding: var(--space-6);
        }

        .card-title {
          font-size: var(--text-lg);
          font-weight: var(--font-semibold);
          color: var(--secondary-900);
          margin: 0 0 var(--space-4) 0;
        }

        .performance-chart {
          text-align: center;
        }

        .performance-circle {
          width: 120px;
          height: 120px;
          border-radius: 50%;
          background: conic-gradient(var(--success-500) 0deg 342deg, var(--secondary-200) 342deg 360deg);
          display: flex;
          align-items: center;
          justify-content: center;
          margin: 0 auto var(--space-4);
          position: relative;
        }

        .performance-circle::before {
          content: '';
          position: absolute;
          width: 80px;
          height: 80px;
          background: white;
          border-radius: 50%;
        }

        .performance-value {
          font-size: var(--text-2xl);
          font-weight: var(--font-bold);
          color: var(--secondary-900);
          position: relative;
          z-index: 1;
        }

        .performance-label {
          color: var(--secondary-600);
          font-size: var(--text-sm);
          margin: 0;
        }

        .activity-list {
          display: flex;
          flex-direction: column;
          gap: var(--space-4);
        }

        .activity-item {
          display: flex;
          align-items: center;
          gap: var(--space-3);
        }

        .activity-icon {
          width: 32px;
          height: 32px;
          border-radius: var(--radius-lg);
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: var(--text-sm);
          flex-shrink: 0;
        }

        .activity-icon.success {
          background-color: var(--success-100);
          color: var(--success-600);
        }

        .activity-icon.warning {
          background-color: var(--warning-100);
          color: var(--warning-600);
        }

        .activity-icon.primary {
          background-color: var(--primary-100);
          color: var(--primary-600);
        }

        .activity-content {
          flex: 1;
        }

        .activity-text {
          font-size: var(--text-sm);
          color: var(--secondary-800);
          margin: 0 0 var(--space-1) 0;
        }

        .activity-time {
          font-size: var(--text-xs);
          color: var(--secondary-500);
          margin: 0;
        }

        .team-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
          gap: var(--space-6);
        }

        .employee-card {
          background: var(--secondary-50);
          border: 1px solid var(--secondary-200);
          border-radius: var(--radius-xl);
          padding: var(--space-6);
          transition: all var(--transition-base);
        }

        .employee-card:hover {
          box-shadow: var(--shadow-md);
          transform: translateY(-2px);
        }

        .employee-avatar {
          width: 48px;
          height: 48px;
          border-radius: var(--radius-full);
          background: linear-gradient(135deg, var(--primary-600), var(--primary-700));
          display: flex;
          align-items: center;
          justify-content: center;
          color: white;
          font-size: var(--text-lg);
          font-weight: var(--font-bold);
          margin-bottom: var(--space-4);
        }

        .employee-name {
          font-size: var(--text-lg);
          font-weight: var(--font-semibold);
          color: var(--secondary-900);
          margin: 0 0 var(--space-1) 0;
        }

        .employee-department {
          color: var(--secondary-600);
          font-size: var(--text-sm);
          margin: 0 0 var(--space-4) 0;
        }

        .employee-stats {
          display: flex;
          gap: var(--space-6);
          margin-bottom: var(--space-4);
        }

        .stat {
          text-align: center;
        }

        .stat-value {
          display: block;
          font-size: var(--text-lg);
          font-weight: var(--font-bold);
          color: var(--secondary-900);
        }

        .stat-label {
          font-size: var(--text-xs);
          color: var(--secondary-500);
        }

        .table-container {
          background: white;
          border-radius: var(--radius-xl);
          overflow: hidden;
          border: 1px solid var(--secondary-200);
        }

        .table {
          width: 100%;
          border-collapse: collapse;
        }

        .table th {
          background-color: var(--secondary-50);
          padding: var(--space-4);
          text-align: left;
          font-weight: var(--font-semibold);
          color: var(--secondary-700);
          font-size: var(--text-sm);
          border-bottom: 1px solid var(--secondary-200);
        }

        .table td {
          padding: var(--space-4);
          border-bottom: 1px solid var(--secondary-100);
          color: var(--secondary-800);
        }

        .table tbody tr:hover {
          background-color: var(--secondary-25);
        }

        .table tbody tr:last-child td {
          border-bottom: none;
        }

        .employee-cell {
          display: flex;
          align-items: center;
          gap: var(--space-3);
        }

        .employee-avatar-sm {
          width: 32px;
          height: 32px;
          border-radius: var(--radius-full);
          background: linear-gradient(135deg, var(--primary-600), var(--primary-700));
          display: flex;
          align-items: center;
          justify-content: center;
          color: white;
          font-size: var(--text-sm);
          font-weight: var(--font-bold);
        }

        .bill-description {
          font-weight: var(--font-medium);
          color: var(--secondary-900);
        }

        .amount {
          font-weight: var(--font-semibold);
          color: var(--success-600);
        }

        .date {
          color: var(--secondary-600);
          font-size: var(--text-sm);
        }

        .action-buttons {
          display: flex;
          gap: var(--space-2);
        }

        .badge {
          display: inline-flex;
          align-items: center;
          padding: var(--space-1) var(--space-3);
          font-size: var(--text-xs);
          font-weight: var(--font-medium);
          border-radius: var(--radius-full);
        }

        .badge-secondary {
          background-color: var(--secondary-100);
          color: var(--secondary-800);
        }

        .btn {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          gap: var(--space-2);
          padding: var(--space-3) var(--space-6);
          font-size: var(--text-sm);
          font-weight: var(--font-medium);
          border: 1px solid transparent;
          border-radius: var(--radius-lg);
          cursor: pointer;
          transition: all var(--transition-fast);
          text-decoration: none;
          white-space: nowrap;
        }

        .btn:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .btn-primary {
          background-color: var(--primary-600);
          color: white;
          border-color: var(--primary-600);
        }

        .btn-primary:hover:not(:disabled) {
          background-color: var(--primary-700);
          border-color: var(--primary-700);
          transform: translateY(-1px);
          box-shadow: var(--shadow-md);
        }

        .btn-outline {
          background-color: transparent;
          color: var(--primary-600);
          border-color: var(--primary-600);
        }

        .btn-outline:hover:not(:disabled) {
          background-color: var(--primary-50);
          color: var(--primary-700);
          border-color: var(--primary-700);
        }

        .btn-success {
          background-color: var(--success-600);
          color: white;
          border-color: var(--success-600);
        }

        .btn-success:hover:not(:disabled) {
          background-color: var(--success-700);
          border-color: var(--success-700);
        }

        .btn-error {
          background-color: var(--error-600);
          color: white;
          border-color: var(--error-600);
        }

        .btn-error:hover:not(:disabled) {
          background-color: var(--error-700);
          border-color: var(--error-700);
        }

        .btn-sm {
          padding: var(--space-2) var(--space-4);
          font-size: var(--text-xs);
        }

        .btn svg {
          width: 16px;
          height: 16px;
        }

        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }

        @media (max-width: 768px) {
          .manager-dashboard {
            padding: var(--space-4);
          }

          .header-content {
            flex-direction: column;
            gap: var(--space-4);
            text-align: center;
          }

          .header-actions {
            flex-direction: column;
            width: 100%;
          }

          .stats-grid {
            grid-template-columns: 1fr;
          }

          .overview-grid {
            grid-template-columns: 1fr;
          }

          .team-grid {
            grid-template-columns: 1fr;
          }

          .section-header {
            flex-direction: column;
            gap: var(--space-4);
            align-items: stretch;
          }

          .section-actions {
            flex-direction: column;
          }

          .action-buttons {
            flex-direction: column;
          }

          .nav-tabs {
            justify-content: center;
          }

          .table-container {
            overflow-x: auto;
          }

          .employee-stats {
            justify-content: center;
          }
        }
      `}</style>
    </div>
  );
};

export default EnhancedManagerDashboard;
